# Analyze maximal axis-aligned all-free rectangles for each 4-connected component, D4.
def get_components(inp, wall):
 h=len(inp);w=len(inp[0]);seen=set();out=[]
 for r in range(h):
  for c in range(w):
   if inp[r][c]==wall or (r,c) in seen:continue
   q=[(r,c)];seen.add((r,c));cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<h and 0<=ny<w and inp[nx][ny]!=wall and (nx,ny) not in seen:seen.add((nx,ny));q.append((nx,ny))
   out.append(set(cells))
 return out
